22:const PANEL_LEFT = 24;
23:const PILL_TOP = 212;
24:const PILL: GlassRect = { x: 0, y: 0, w: 293, h: 56, r: 20 };
25:
26:const MENU_OFFSET_Y = 68; // .fusionMenuContainer : top 280
27:const MENU_W = 320;
28:const MENU_R = 16;
29:// Panneau (max-height 400) + la marge que prend le col en s'étirant avant de se rompre.
30:const MENU_STAGE_H = MENU_OFFSET_Y + 400 + 40;
31:const MENU_MORPH_MS = 700;
