33:// Prévisualisation : panneau du haut sur toute la hauteur disponible, panneau du bas de hauteur
34:// fixe, le tout s'arrêtant à 236px du bas de l'écran (au-dessus de la barre d'aide).
35:const PREVIEW_W = 344;
36:const PREVIEW_R = 20;
37:const PREVIEW_GAP = 16;
38:const PREVIEW_LOWER_H = 250;
39:const PREVIEW_BOTTOM_MARGIN = 236;
40:const PREVIEW_UPPER_MIN_H = 120;
41:const PREVIEW_STRETCH_MS = 520;
42:const PREVIEW_HOLD_MS = 90; // temps mort entre l'étirement et la division : deux gestes distincts
43:const PREVIEW_DIVIDE_MS = 760;
44:const PREVIEW_MORPH_MS = PREVIEW_STRETCH_MS + PREVIEW_HOLD_MS + PREVIEW_DIVIDE_MS;
45:
46:const previewGeometry = (viewportH: number) => {
47:  const upperH = Math.max(
48:    PREVIEW_UPPER_MIN_H,
49:    viewportH - PREVIEW_BOTTOM_MARGIN - PREVIEW_LOWER_H - PREVIEW_GAP - PILL_TOP,
50:  );
51:  const upper: GlassRect = { x: 0, y: 0, w: PREVIEW_W, h: upperH, r: PREVIEW_R };
52:  const lower: GlassRect = { x: 0, y: upperH + PREVIEW_GAP, w: PREVIEW_W, h: PREVIEW_LOWER_H, r: PREVIEW_R };
53:  // + marge pour le col qui s'étire avant la rupture.
54:  return { upper, lower, stageH: lower.y + lower.h + 40 };
55:};
