67:const modelingGeometry = (viewportH: number): GlassRect => ({
68:  x: 0,
69:  y: MODELING_Y,
70:  w: MODELING_W,
71:  h: viewportH - 96 - MODELING_BOTTOM_MARGIN,
72:  r: MODELING_R,
73:});
