          top={PILL_TOP}
          width={MENU_W}
          height={MENU_STAGE_H}
          duration={MENU_MORPH_MS}
          pathAt={menuPathAt}
          reverse={morphPhase === 'merging'}
          onDone={() => {
            if (morphPhase === 'merging') onSelectCategory(null);
            setMorphPhase(null);
          }}
        />
      )}

      {/* Morph vers le panneau Modélisation : part de la pilule seule (stretchPath) ou des deux
          panneaux de Prévisualisation (fusePath) selon fromPreview — cf. modelingPathAt. Le stage
          doit englober tout ce que la géométrie de départ ET celle d'arrivée occupent (le panneau
          Modélisation remonte au-dessus du niveau de la pilule : MODELING_Y est négatif). Ne se
          rejoue jamais (onDone se contente de prévenir Index.tsx, qui démonte ce composant). */}
      {modelingMorphActive && (() => {
        const target = modelingGeometry(window.innerHeight);
        const top0 = Math.min(0, target.y) - 20;
        const bottom0 = Math.max(previewGeo.stageH, target.y + target.h) + 20;
        return (
          <LiquidGlassMorph
            left={PANEL_LEFT}
            top={PILL_TOP + top0}
            width={Math.max(PREVIEW_W, target.w) + 20}
            height={bottom0 - top0}
            duration={MODELING_MORPH_MS}
            pathAt={(t, dx, dy) => modelingPathAt(t, dx, dy - top0)}
            onDone={() => {
              setModelingMorphActive(false);
              morphToModelingRef.current?.onDone();
            }}
          />
        );
      })()}

      <AnimatePresence>
        {activeCatData && !activeCatData.disabled && (
          <>
            {/* Toujours ouvert/fermé par un morphing : pas d'animation d'entrée ni de sortie
                propre, le verre animé en tient lieu (.morphing masque le fond de ce panneau et
                estompe son contenu pendant ce temps). */}
            <motion.div
              ref={menuContainerRef}
              className={clsx(styles.fusionMenuContainer, {
                [styles.morphing]: morphPhase !== null,
              })}
              initial={false}
              exit={{ opacity: 0 }}
              transition={{ duration: 0 }}
            >
              <div
                ref={contentRef}
                className={clsx(styles.fusionMenuContent, styles.contentInert)}
                onScroll={handleScroll}
              >
                {activeCatData.sections.map((section, idx) => (
                  <div key={idx} className={styles.sectionGroup}>
                    <h4 className={styles.sectionTitle}>{section.title}</h4>
                    <ul className={styles.itemsList}>
                      {section.items.map((item, iIdx) => (
                        <CustomTooltip key={iIdx} content="Arrive bientôt" description={item.description}>
                          <li className={styles.itemRow}>
                            <span className={styles.itemName}>
                              {item.isPatternDropdown ? `Motif de remplissage (${selectedPattern})` : item.label}
                            </span>
                            {item.isPatternDropdown ? (
                              <ChevronDown size={14} className="shrink-0 text-white/40 -rotate-90 ml-2" />
                            ) : (
                              <input
                                type="text"
                                defaultValue={item.defaultValue}
                                className={styles.itemInput}
                                readOnly
                                tabIndex={-1}
                              />
                            )}
                          </li>
                        </CustomTooltip>
                      ))}
                    </ul>
                  </div>
                ))}
              </div>

              {hasScroll && (
                <div 
                  className={clsx(styles.externalScrollThumb, { [styles.dragging]: isDragging })}
                  onMouseDown={handleMouseDown}
                  style={{
                    height: `${thumbHeight}px`,
                    top: `${thumbTop}px`
                  }}
                />
              )}
            </motion.div>

            {/* Pattern popup window next to the menu */}
            <AnimatePresence>
              {isPatternPopupOpen && (
                <motion.div
                  className={styles.patternPopup}
                  initial={{ opacity: 0, scale: 0.95, x: -10 }}
                  animate={{ opacity: 1, scale: 1, x: 0 }}
                  exit={{ opacity: 0, scale: 0.95, x: -10 }}
                  transition={{ duration: 0.2, ease: [0.16, 1, 0.3, 1] }}
                >
                  <div 
                    ref={patternContentRef}
                    className={styles.patternPopupContent}
                    onScroll={handlePatternScroll}
                  >
                    <div className={styles.sectionGroup}>
                      <h4 className={styles.sectionTitle}>Motifs de remplissage</h4>
                      <ul className={styles.itemsList}>
                        {INFILL_PATTERNS.map((pat, pIdx) => {
                          const isSelected = selectedPattern === pat.name;
                          return (
                            <CustomTooltip key={pIdx} content={pat.name} description={pat.description} key-override={pat.name}>
                              <li 
                                className={clsx(styles.patternItem, { [styles.activePattern]: isSelected })}
                                onClick={() => {
                                  setSelectedPattern(pat.name);
                                  setIsPatternPopupOpen(false);
                                }}
                              >
                                <span className={styles.itemName}>{pat.name}</span>
                                {isSelected && <Check size={14} className="text-[#00f0ff] shrink-0" />}
                              </li>
                            </CustomTooltip>
                          );
                        })}
                      </ul>
                    </div>
                  </div>

                  {hasPatternScroll && (
                    <div 
                      className={clsx(styles.externalScrollThumb, { [styles.dragging]: isPatternDragging })}
                      onMouseDown={handlePatternMouseDown}
                      style={{
                        height: `${patternThumbHeight}px`,
                        top: `${patternThumbTop}px`
                      }}
                    />
                  )}
                </motion.div>
              )}
            </AnimatePresence>
          </>
        )}
      </AnimatePresence>
    </>
  );
};

