onDone={() => {
  // Le vrai panneau Modélisation (ModelingSidebar) doit être peint AVANT que le verre
  // ne soit retiré du DOM, sinon les deux updates arrivant dans le même geste React
  // (donc la même frame), le navigateur peut composer une image où ni l'un ni l'autre
  // n'est encore opaque à cet endroit — un clignotement. `onDone()` démasque d'abord
  // le vrai panneau (Index.tsx : hidden passe à false) ; on laisse le temps à deux
  // frames de s'écouler (style recalc + paint) avant de démonter le verre et les
  // panneaux de Prévisualisation, pour garantir un chevauchement.
  morphToModelingRef.current?.onDone();
  requestAnimationFrame(() => {
    requestAnimationFrame(() => {
      setModelingMorphActive(false);
    });
  });
}}

input.new_string:
onDone={() => {
  // Le vrai panneau Modélisation (ModelingSidebar) doit être peint AVANT que le verre
  // ne soit retiré du DOM : `onRevealed` démasque ce panneau (Index.tsx passe son
  // `hidden` à false) sans démonter ce composant. On laisse ensuite le temps à deux
  // frames de s'écouler (style recalc + paint) avant de prévenir Index.tsx (`onDone`)
  // qu'il peut enfin démonter ce composant et son verre — sans ce délai, les deux
  // updates arriveraient dans le même geste React, donc la même frame peinte, sans
  // garantie qu'un des deux calques soit déjà opaque à l'écran : un clignotement.
  morphToModelingRef.current?.onRevealed();
  requestAnimationFrame(() => {
    requestAnimationFrame(() => {
      setModelingMorphActive(false);
      morphToModelingRef.current?.onDone();
    });
  });
}}

