const [isSliceModalOpen, setIsSliceModalOpen] = useState(false);
const [isSlicingProgressOpen, setIsSlicingProgressOpen] = useState(false);
const [modelStatus, setModelStatus] = useState<ModelStatus | null>(null);
const [isPreviewActive, setIsPreviewActive] = useState(false);
const isPreviewActiveRef = useRef(isPreviewActive);
isPreviewActiveRef.current = isPreviewActive;
// Le temps que CategoriesSidebar déforme la pilule (ou les deux panneaux de Prévisualisation)
// vers le panneau Modélisation — cf. le commentaire sur `onTabChange` plus bas. `null` = pas de
// morph en cours ; sinon, l'état de départ figé à l'instant du clic (lu depuis
// isPreviewActiveRef, PAS depuis isPreviewActive : Sidebar mute ce dernier vers `false` dans le
// même geste, avant que CategoriesSidebar n'ait eu la chance de lire sa valeur de départ).
const [modelingMorphFrom, setModelingMorphFrom] = useState<{ fromPreview: boolean } | null>(null);
// Démasqué (ModelingSidebar `hidden` → false) dès la fin du morph, tout en gardant
// CategoriesSidebar (et son verre encore affiché à cet instant) montée quelques frames de plus —
// cf. l'appel à `onModelingRevealed` de <CategoriesSidebar morphToModeling>. Sans ce délai, le
// démasquage du vrai panneau ET le démontage du verre arriveraient dans le même geste React,
// donc la même frame peinte, et rien d'opaque ne serait garanti affiché à cet endroit entre les
// deux — un clignotement.
const [modelingRevealed, setModelingRevealed] = useState(false);
const [statusBarRef, animateStatusBar] = useAnimate<HTMLDivElement>();
const prevPreviewActiveRef = useRef(isPreviewActive);

// Au changement d'espace, la barre d'aide (TopRightMenu) passe par le coin bas gauche, là où
// se trouve la barre de statut : celle-ci se rentre sous le bord de l'écran juste avant
// (0,2 → 0,45 s ; la barre d'aide démarre à 0,495 s) et ressort une fois la barre d'aide
// arrivée (1,1 s), pour ne pas se faire recouvrir.
useEffect(() => {
  if (prevPreviewActiveRef.current === isPreviewActive) return;
  prevPreviewActiveRef.current = isPreviewActive;
  if (!statusBarRef.current) return;
  animateStatusBar(
    statusBarRef.current,
    { y: [0, 0, 80, 80, 0] },
    { duration: 1.4, times: [0, 0.2 / 1.4, 0.45 / 1.4, 1.1 / 1.4, 1], ease: [0.25, 1, 0.5, 1] },
  );
}, [isPreviewActive, animateStatusBar, statusBarRef]);

/** L'onglet « Modélisation » de la Sidebar porte la valeur 'settings'. */
const isModeling = activeTab === 'settings';

React.useEffect(() => {
  const handleModelSelected = (event: CustomEvent<{
    name: string | null;
    dimensions?: { x: number; y: number; z: number };
  }>) => {
    if (!event.detail?.name) {
      setModelStatus(null);
      return;
    }

    setModelStatus({
      name: event.detail.name,
      dimensions: event.detail.dimensions ?? null,
    });
  };

{/* Les panneaux slicer et le panneau modélisation s'excluent mutuellement : basculer
    d'onglet échange les deux avec un fondu, plutôt que de les empiler — sauf pendant un
    morph vers Modélisation (modelingMorphFrom), où CategoriesSidebar reste monté par-dessus
    le temps de terminer son animation (cf. son morphToModeling). */}
<AnimatePresence mode={modelingMorphFrom ? 'sync' : 'wait'}>
  {isModeling ? (
    <React.Fragment key="modeling">
      <ModelingSidebar hidden={!!modelingMorphFrom && !modelingRevealed} />
      {modelingMorphFrom && (
        <CategoriesSidebar
          activeCategory={activeCategory}
          onSelectCategory={() => {}}
          morphToModeling={{
            ...modelingMorphFrom,
            // Démasque d'abord le vrai panneau (ModelingSidebar), sans démonter
            // CategoriesSidebar : le verre reste affiché par-dessus jusqu'à ce que
            // CategoriesSidebar confirme (onDone) que le panneau est bien peint.
            onRevealed: () => setModelingRevealed(true),
            onDone: () => setModelingMorphFrom(null),

