const modelingPathAt = useCallback((t: number, dx: number, dy: number) => {
  const target = modelingGeometry(window.innerHeight);
  if (morphToModelingRef.current?.fromPreview) {
    const { upper, lower } = previewGeometry(window.innerHeight);
    return fusePath(upper, lower, target, t, dx, dy);
  }
  return stretchPath(PILL, target, t, dx, dy);
}, []);

