export const PREVIEW_GAP = 16;
export const PREVIEW_LOWER_H = 250;
export const PREVIEW_BOTTOM_MARGIN = 236;
export const PREVIEW_UPPER_MIN_H = 120;

export const previewGeometry = (viewportH: number) => {
  const upperH = Math.max(
    PREVIEW_UPPER_MIN_H,
