interface CategoriesSidebarProps {
  activeCategory: string | null;
  onSelectCategory: (catId: string | null) => void;
  /**
   * Signale un morph entre l'espace Modélisation et la pilule/les panneaux de Prévisualisation,
   * dans un sens ou dans l'autre :
   *  - 'enter' : la pilule (ou les deux panneaux de Prévisualisation, si `fromPreview` est vrai)
   *    se déforme en un seul geste vers la forme/position du panneau Modélisation. Cette instance
   *    affiche les vrais éléments de départ (pilule ou panneaux Preview) pendant le morph, sans
   *    fond (cf. .morphing), le verre animé en tenant lieu.
   *  - 'exit' : mouvement inverse — le panneau Modélisation (déjà affiché par une AUTRE instance
   *    de ModelingSidebar, gardée montée par Index.tsx) se déforme vers la pilule ou les panneaux
   *    de Prévisualisation. Cette instance-ci n'affiche AUCUN élément réel avant la fin du morph
   *    (rien à estomper : le panneau de départ est le panneau Modélisation, pas un de ses propres
   *    éléments) — seul le verre est visible, démarrant sur la géométrie Modélisation.
   *
   * Dans les deux cas, `onRevealed` est appelé dès la dernière image du morph posée (le panneau
   * réel d'arrivée — Modélisation en 'enter', pilule/Prévisualisation en 'exit' — doit alors être
   * démasqué côté Index.tsx), `onDone` seulement quelques frames plus tard (c'est seulement à ce
   * moment qu'Index.tsx doit démonter cette instance — jamais avant `onRevealed`, sinon le morph
   * n'aurait rien à quoi se raccorder, et jamais en même temps non plus, sinon le démasquage du
   * panneau réel et le démontage du verre arrivent à la même frame peinte : un clignotement). Ce
   * composant est remonté à neuf pour ce morph (cf. sa `key` dans Index.tsx), donc l'état de départ
   * doit venir d'une prop plutôt que d'un state interne qui repartirait de zéro.
   */
  morphToModeling?: { direction: 'enter' | 'exit'; fromPreview: boolean; onRevealed: () => void; onDone: () => void };
}

export const CategoriesSidebar: React.FC<CategoriesSidebarProps> = ({
  activeCategory,
  onSelectCategory,
  morphToModeling,
}) => {
  const iconRefs = useRef<{ [key: string]: HTMLButtonElement | null }>({});
  const categoriesToolbarRef = useRef<HTMLDivElement>(null);
  const contentRef = useRef<HTMLDivElement>(null);
  const patternContentRef = useRef<HTMLDivElement>(null);

  const [thumbHeight, setThumbHeight] = useState(40);
  const [thumbTop, setThumbTop] = useState(8);
  const [hasScroll, setHasScroll] = useState(false);
  const [isDragging, setIsDragging] = useState(false);

  const [patternThumbHeight, setPatternThumbHeight] = useState(40);
  const [patternThumbTop, setPatternThumbTop] = useState(8);
  const [hasPatternScroll, setHasPatternScroll] = useState(false);
  const [isPatternDragging, setIsPatternDragging] = useState(false);

  const [selectedPattern, setSelectedPattern] = useState<string>('Gyroïde');
  const [isPatternPopupOpen, setIsPatternPopupOpen] = useState(false);
  // Initialisés depuis morphToModeling quand ce composant est remonté à neuf pour un morph 'enter'
  // lancé depuis Prévisualisation (cf. sa `key` dans Index.tsx) : les deux panneaux réels doivent
  // être affichés dès le premier rendu, pas après un aller-retour à `false`. Jamais vrai en 'exit'
  // (cf. le commentaire sur morphToModeling) : cette instance n'affiche aucun élément réel avant
  // que le morph inverse ne soit terminé.
  const morphEntersFromPreview = morphToModeling?.direction === 'enter' && morphToModeling.fromPreview;
  const [previewActive, setPreviewActive] = useState(() => !!morphEntersFromPreview);
  const [previewPanelsBornInit] = useState(() => !!morphEntersFromPreview);

  // Morphings "verre liquide" (cf. LiquidGlassMorph). Pendant qu'une forme animée est à l'écran,
  // les vrais éléments restent montés mais sans fond (classe .morphing) : seul leur contenu
  // s'estompe, par-dessus le verre animé qui en tient lieu.
  //
  // Menu de catégorie :
  //  - 'dividing' : la pilule enfante le panneau détaillé (ouverture)
  //  - 'merging'  : le panneau remonte se refondre dans la pilule (fermeture)
  const [morphPhase, setMorphPhase] = useState<'dividing' | 'merging' | null>(null);
  const menuContainerRef = useRef<HTMLDivElement>(null);

  // Espace Prévisualisation : à l'entrée, la pilule s'étire en panneau du haut, PUIS ce panneau
  // enfante celui du bas (deux temps successifs d'une même timeline, cf. previewPathAt) ; les deux
  // panneaux restent affichés tant qu'on reste dans l'espace. À la sortie, la même timeline est
  // rejouée à l'envers (reverse) : les deux panneaux se refondent en pilule.
  //  - 'forward' : pilule → panneau haut → panneau bas (ouverture)
  //  - 'reverse' : panneau bas → panneau haut → pilule (fermeture)
  const [previewMorphPhase, setPreviewMorphPhase] = useState<'forward' | 'reverse' | null>(null);
  const [previewPanelsBorn, setPreviewPanelsBorn] = useState(previewPanelsBornInit);
  const previewActiveRef = useRef(previewPanelsBornInit);
  const onSelectCategoryRef = useRef(onSelectCategory);
  onSelectCategoryRef.current = onSelectCategory;

  // Morph vers le panneau Modélisation (cf. la prop morphToModeling) : part de la pilule seule
  // (stretchPath) ou des deux panneaux de Prévisualisation (fusePath) selon l'état de départ figé
  // par Index.tsx, déclenché une seule fois au montage de cette instance dédiée.
  const [modelingMorphActive, setModelingMorphActive] = useState(!!morphToModeling);
  const morphToModelingRef = useRef(morphToModeling);
  morphToModelingRef.current = morphToModeling;

  const startYRef = useRef(0);
  const startScrollTopRef = useRef(0);

  useEffect(() => {
    const handlePreviewToggled = (e: CustomEvent<{ active: boolean }>) => {
      // Une instance dédiée à un morph (cf. morphToModeling) ne réagit jamais à cet événement :
      // en 'enter' comme en 'exit', c'est son propre morph (déclenché une seule fois au montage,
      // cf. plus bas) qui pilote entièrement l'affichage, jamais la mitose normale de
      // Prévisualisation — sans quoi les deux entreraient en conflit sur les mêmes states.
      if (morphToModelingRef.current) return;
      const active = !!e.detail?.active;
      if (active && !previewActiveRef.current) {
        // La pilule devient le panneau du haut : un menu de catégorie encore ouvert se ferme
        // sans animation plutôt que de se superposer à la mitose.
        setMorphPhase(null);
        onSelectCategoryRef.current(null);
        setPreviewPanelsBorn(false);
        setPreviewMorphPhase('forward');
      } else if (!active && previewActiveRef.current) {
        // Sortie de l'espace : les deux panneaux se refondent en pilule (même timeline, à
        // l'envers) avant de démonter — jamais de disparition instantanée. `previewActive` lui-
        // même ne repasse à false qu'à la fin de cette animation (cf. onDone du morph), pour que
        // les panneaux réels restent montés (silencieux, cf. .morphing) tout du long.
        setPreviewMorphPhase('reverse');
        return;
      }
      previewActiveRef.current = active;
      setPreviewActive(active);
    };
    window.addEventListener('apex-preview-toggled', handlePreviewToggled as EventListener);

