"use client";

import React, { useEffect, useRef, useState } from 'react';
import { Sidebar } from '@/components/Sidebar';
import { FileSidebar } from '@/components/FileSidebar';
import { SliceSidebar } from '@/components/SliceSidebar';
import { CategoriesSidebar } from '@/components/CategoriesSidebar';
import { PrinterConfigSidebar } from '@/components/PrinterConfigSidebar';
import { AxisSidebar } from '@/components/AxisSidebar';
import { ModelingSidebar } from '@/components/ModelingSidebar';
import { TopRightMenu } from '@/components/TopRightMenu';
import { ModelStatusBox } from '@/components/ModelStatusBox';
import { ModelHoverTooltip } from '@/components/ModelHoverTooltip';
import { TextureEditorModal } from '@/components/TextureEditorModal';
import { SliceModal } from '@/components/SliceModal';
import { SlicingProgressModal } from '@/components/SlicingProgressModal';
import { ViewCube } from '@/components/ViewCube';
import { Viewport3D } from '@/components/Viewport3D';
import { SpaceTransitionOverlay } from '@/components/SpaceTransitionOverlay';
import { GCodePreview } from '@/components/GCodePreview';
import { AnimatePresence, useAnimate } from 'framer-motion';
import { Box } from 'lucide-react';
import { showSuccess } from '@/utils/toast';

interface ModelStatus {
  name: string;
  dimensions: { x: number; y: number; z: number } | null;
}

const Index = () => {
  const [activeTab, setActiveTab] = useState<'3d-view' | 'settings' | 'developer'>('3d-view');
  const [activeCategory, setActiveCategory] = useState<string | null>(null);
  const [isPrinterConfigOpen, setIsPrinterConfigOpen] = useState(false);
  const [selectedPrinter, setSelectedPrinter] = useState('Prusa MK4');
  const [selectedFilament, setSelectedFilament] = useState('PLA Premium (eSUN / Prusament)');
  const [isSliceModalOpen, setIsSliceModalOpen] = useState(false);
  const [isSlicingProgressOpen, setIsSlicingProgressOpen] = useState(false);
  const [modelStatus, setModelStatus] = useState<ModelStatus | null>(null);
  const [isPreviewActive, setIsPreviewActive] = useState(false);
  const isPreviewActiveRef = useRef(isPreviewActive);
  isPreviewActiveRef.current = isPreviewActive;
  // Le temps que CategoriesSidebar déforme la pilule (ou les deux panneaux de Prévisualisation)
  // vers le panneau Modélisation, ou inversement — cf. le commentaire sur `onTabChange` plus bas.
  // `null` = pas de morph en cours ; sinon, `direction` indique le sens ('enter' : vers
  // Modélisation, 'exit' : hors de Modélisation) et `fromPreview`/`toPreview` (même champ, son nom
  // dépend juste du sens de lecture) l'état de Prévisualisation à l'autre bout du morph — figé à
  // l'instant du clic, lu depuis isPreviewActiveRef, PAS depuis isPreviewActive : Sidebar mute ce
  // dernier dans le même geste, avant que CategoriesSidebar n'ait la chance de lire sa valeur de
  // départ.
  const [modelingMorph, setModelingMorph] = useState<{ direction: 'enter' | 'exit'; fromPreview: boolean } | null>(null);
  // Démasqué (ModelingSidebar `hidden` → false) dès la fin d'un morph 'enter', tout en gardant
  // CategoriesSidebar (et son verre encore affiché à cet instant) montée quelques frames de plus —
  // cf. l'appel à `onRevealed` de <CategoriesSidebar modelingMorph>. Sans ce délai, le démasquage
  // du vrai panneau et le démontage du verre arriveraient dans le même geste React, donc la même
  // frame peinte, et rien d'opaque ne serait garanti affiché à cet endroit entre les deux — un
  // clignotement.
  const [modelingRevealed, setModelingRevealed] = useState(false);
  // Symétrique de `modelingRevealed`, pour un morph 'exit' : les panneaux slicer normaux
  // (Prévisualisation ou Préparation) ne sont démasqués qu'à la fin du morph, et ModelingSidebar
  // n'est démonté que quelques frames plus tard, pour la même raison.

