file.content:
    d'onglet échange les deux avec un fondu, plutôt que de les empiler — sauf pendant un
    morph vers ou hors de Modélisation (modelingMorph), où les deux restent montés le temps
    que l'animation se termine (cf. CategoriesSidebar/son morphToModeling). */}
<AnimatePresence mode={modelingMorph ? 'sync' : 'wait'}>
  {isModeling ? (
    <React.Fragment key="modeling">
      <ModelingSidebar hidden={!!modelingMorph && !modelingRevealed} />
      {modelingMorph && (
        <CategoriesSidebar
          activeCategory={activeCategory}
          onSelectCategory={() => {}}
          morphToModeling={{
            ...modelingMorph,
            // Démasque d'abord le vrai panneau (ModelingSidebar), sans démonter
            // CategoriesSidebar : le verre reste affiché par-dessus jusqu'à ce que
            // CategoriesSidebar confirme (onDone) que le panneau est bien peint.
            onRevealed: () => setModelingRevealed(true),
            onDone: () => setModelingMorph(null),
          }}
        />
      )}
    </React.Fragment>
  ) : (
    <React.Fragment key="slicer">
      {/* Pendant un morph de sortie de Modélisation ('exit'), ModelingSidebar reste monté
          (encore visible, cf. son `hidden`) par-dessus une instance dédiée de
          CategoriesSidebar qui joue l'animation inverse — jamais l'instance normale
          ci-dessous, dont le state interne (previewActive, etc.) suit l'état RÉEL courant et
          ne doit pas être perturbé par un morph qui n'a pas encore fini. Cette instance
          dédiée est démontée (onDone) une fois le panneau normal démasqué et peint,
          exactement comme son pendant pour 'enter' juste au-dessus. */}
      {modelingMorph?.direction === 'exit' ? (
        <>
          <ModelingSidebar hidden={slicerRevealed} />
          <CategoriesSidebar
            activeCategory={activeCategory}
            onSelectCategory={() => {}}
            morphToModeling={{
              ...modelingMorph,
              onRevealed: () => setSlicerRevealed(true),
              onDone: () => setModelingMorph(null),
            }}
          />
        </>
      ) : (
        <CategoriesSidebar
          activeCategory={activeCategory}
          onSelectCategory={(cat) => {
            setActiveCategory(cat);
            if (cat) setIsPrinterConfigOpen(false);
          }}
        />
      )}

      <PrinterConfigSidebar
        isOpen={isPrinterConfigOpen}
        onClose={() => setIsPrinterConfigOpen(false)}
        selectedPrinter={selectedPrinter}
        onSelectPrinter={setSelectedPrinter}
        selectedFilament={selectedFilament}
        onSelectFilament={setSelectedFilament}
      />

      <SliceSidebar onSlice={handleSlice} />
    </React.Fragment>

