// Morph d'espace (cf. la prop `morph`) : anime directement le `clip-path` de .panel entre la
// forme de la pilule/des panneaux Preview et sa forme normale — jamais de calque séparé à
// raccorder. `morphActive` reste vrai un instant de plus que `morph` lui-même (il ne redevient
// false qu'une fois le style inline de secours retiré), pour ne jamais laisser passer une frame
// avec le clip-path de la dernière image du morph mais déjà les classes CSS normales.
const panelRef = useRef<HTMLDivElement>(null);
const [morphActive, setMorphActive] = useState(!!morph);
const morphRef = useRef(morph);
morphRef.current = morph;
const stage = modelingMorphStage(typeof window !== 'undefined' ? window.innerHeight : 1080);

useLiquidGlassClip(
  panelRef,
  {
    duration: MODELING_MORPH_MS,
    reverse: morph?.direction === 'exit',
    pathAt: (t, dx, dy) => modelingPathAt(!!morph?.fromPreview, window.innerHeight, t, dx, dy - stage.dyOffset),
    onDone: () => {
      setMorphActive(false);
      morphRef.current?.onDone();
    },
  },
  [morph?.direction, morph?.fromPreview],
);

