return (
  <>
    {/* ---------- Panneau latéral : arborescence des corps ---------- */}
    <div className={styles.container} data-apex-chrome-panel style={hidden ? { visibility: 'hidden' } : undefined}>
      <motion.div
        className={styles.panel}
        initial={false}
        animate={{ opacity: hidden ? 0 : 1, x: 0 }}
        exit={{ opacity: 0, x: -24 }}
        // `hidden` bascule tout ou rien, sans transition : ce panneau doit être pleinement
        // opaque dès l'image où le morph (LiquidGlassMorph) le démasque (cf. `onRevealed` dans
        // CategoriesSidebar.tsx), qui ne retire son verre que quelques frames plus tard une fois
        // ce panneau confirmé peint — un fondu ici retarderait l'opacité réelle après coup, ce
        // qui romprait ce chevauchement voulu. Seule la sortie complète (démontage, `exit`)
        // garde une vraie transition, indépendante de `hidden`.
        transition={{ duration: 0 }}
      >
        <div className={styles.header}>
          <Box className={clsx('w-4 h-4', styles.headerIcon)} />
          Modélisation
        </div>

        <div className={styles.sectionLabel}>Sélection</div>
        <div ref={segmentedRef} className={styles.segmented}>
          <div className={styles.activeIndicator} style={indicatorStyle} />
          {SELECTION_MODES.map(({ mode, label, enabled }) => (
            <CustomTooltip
              key={mode}
              content={label}
              description={enabled ? `Sélectionner par ${label.toLowerCase()}.` : 'Arrive bientôt.'}
            >
              <button
                ref={(el) => { if (el) segmentRefs.current.set(mode, el); }}
                className={clsx(styles.segmentButton, { [styles.active]: selectionMode === mode })}
                onClick={() => handleSelectionMode(mode)}
                disabled={!enabled}
              >
                {label}
              </button>
            </CustomTooltip>

