// et dimensions du stage élargi) ne soit retiré qu'après, jamais avant — sans quoi une frame
// laisserait passer soit un clip-path sans le bon stage, soit les classes CSS normales avant que
// le morph n'ait fini d'animer.
const panelRef = useRef<HTMLDivElement>(null);
const [morphStage, setMorphStage] = useState(() => (morph ? modelingMorphStage(window.innerHeight) : null));
const morphRef = useRef(morph);
morphRef.current = morph;

// Layout effect : la première silhouette est posée avant le premier affichage (sinon une image
// du panneau non clippé — donc en pleine forme rectangulaire normale — clignoterait).
useLayoutEffect(() => {
  if (!morph || !panelRef.current) return;
  const stage = modelingMorphStage(window.innerHeight);
  setMorphStage(stage);
  const el = panelRef.current;

  const apply = (progress: number) => {
    const t = morph.direction === 'exit' ? 1 - progress : progress;
    el.style.clipPath = `path('${modelingPathAt(morph.fromPreview, window.innerHeight, t, 0, -stage.dyOffset)}')`;
  };

  apply(0);
  const start = performance.now();
  let raf = requestAnimationFrame(function tick(now) {
    const progress = Math.min(1, (now - start) / MODELING_MORPH_MS);
    apply(progress);
    if (progress < 1) {
      raf = requestAnimationFrame(tick);
    } else {
      el.style.clipPath = '';
      setMorphStage(null);
      morphRef.current?.onDone();
    }
  });
  return () => cancelAnimationFrame(raf);
  // `morph.direction`/`morph.fromPreview` sont figés pour la durée de CE morph (Index.tsx ne les
  // change jamais sans démonter/remonter un nouveau cycle) : seule l'identité de `morph`
  // (passant de undefined à défini) doit relancer l'effet.
  // eslint-disable-next-line react-hooks/exhaustive-deps
}, [morph]);

/** Le viewport a besoin de connaître l'état initial dès le montage du panneau. */
useEffect(() => {
  window.dispatchEvent(new CustomEvent('apex-mode-changed', { detail: { mode: 'modeling' } }));
  window.dispatchEvent(new CustomEvent('apex-selection-mode-changed', { detail: { mode: 'body' } }));

