{/* ---------- Panneau latéral : arborescence des corps ---------- */}
<div
  className={styles.container}
  data-apex-chrome-panel
  style={
    morphStage
      ? { position: 'fixed', left: morphStage.left, top: morphStage.top, width: morphStage.width, height: morphStage.height, bottom: 'auto' }
      : undefined
  }
>
  <motion.div
    ref={panelRef}
    className={clsx(styles.panel, { [styles.morphing]: !!morphStage })}
    initial={false}
    animate={{ opacity: 1, x: 0 }}
    exit={{ opacity: 0, x: -24 }}
    transition={{ duration: 0 }}
  >
    {/* Pendant un morph (cf. `morph`/CONTENT_REVEAL_THRESHOLD), ce contenu reste caché tant
        que la silhouette est trop petite pour l'accueillir lisiblement, puis apparaît groupe
        par groupe (header, Sélection, Corps) plutôt que d'un bloc — cf. contentRevealed /
        contentContainerVariants. Hors morph, `contentRevealed` vaut `true` en permanence :
        `animate="visible"` s'applique sans délai, comme un panneau statique normal. */}
    <motion.div
      variants={contentContainerVariants}
      initial={false}
      animate={contentRevealed ? 'visible' : 'hidden'}
    >
    <motion.div className={styles.header} variants={contentGroupVariants}>
      <Box className={clsx('w-4 h-4', styles.headerIcon)} />

