112	   * Prévisualisation, dans un sens ou dans l'autre :
113	   *  - 'enter' : ce panneau — déjà affiché avec son contenu réel — part de la forme/position de la
114	   *    pilule (ou des deux panneaux de Prévisualisation si `fromPreview`) et se déforme en un seul
115	   *    geste vers sa forme normale.
116	   *  - 'exit' : mouvement inverse — parti de sa forme normale, ce panneau se déforme vers la
117	   *    pilule ou les panneaux de Prévisualisation, puis Index.tsx le démonte (`onDone`) et affiche
118	   *    à la place les vrais panneaux slicer, déjà dans leur état final (cf. `initialPreviewActive`
119	   *    de CategoriesSidebar).
120	   *
121	   * Contrairement à l'ancienne approche (un calque de verre animé séparé, remplacé après coup par
122	   * ce panneau), c'est ICI le même élément DOM, déjà monté avec son contenu réel, qui change de
123	   * silhouette (`clip-path`, cf. useLiquidGlassClip) — aucun raccord entre deux éléments distincts,
124	   * donc aucun risque de clignotement à la jonction. Reste monté pendant tout le morph (les effets
125	   * de montage/démontage — restauration du mode 3D notamment — ne doivent avoir lieu qu'une fois).
126	   */
127	  morph?: { direction: 'enter' | 'exit'; fromPreview: boolean; onDone: () => void };
128	}
129	
130	export const ModelingSidebar: React.FC<ModelingSidebarProps> = ({ morph }) => {
131	  const [models, setModels] = useState<ModelNode[]>([]);
132	  const [selectedModel, setSelectedModel] = useState<string | null>(null);
133	  const [selectedFeatureId, setSelectedFeatureId] = useState<string | null>(null);
134	  const [expanded, setExpanded] = useState<Record<string, boolean>>({});
135	  const [activeTool, setActiveTool] = useState<FeatureKind | null>(null);
136	  const [sketchEntity, setSketchEntity] = useState<SketchEntityKind>('rectangle');
137	  const [selectionMode, setSelectionMode] = useState<SelectionMode>('body');
138	
139	  const segmentedRef = useRef<HTMLDivElement>(null);
140	  const segmentRefs = useRef<Map<string, HTMLButtonElement>>(new Map());
141	  const [indicatorStyle, setIndicatorStyle] = useState<React.CSSProperties>({});
142	
143	  // Morph d'espace (cf. la prop `morph`) : anime directement le `clip-path` de .panel entre la
144	  // forme de la pilule/des panneaux Preview et sa forme normale — jamais de calque séparé à
145	  // raccorder, c'est ce panneau réel, déjà affiché avec son contenu, qui change de silhouette.
146	  // `morphStage` reste défini un instant de plus que `morph` lui-même (il ne redevient `null` que
147	  // dans `onDone`, une fois la dernière image posée), pour que le style inline de secours (position
148	  // et dimensions du stage élargi) ne soit retiré qu'après, jamais avant — sans quoi une frame
149	  // laisserait passer soit un clip-path sans le bon stage, soit les classes CSS normales avant que
150	  // le morph n'ait fini d'animer.
151	  const panelRef = useRef<HTMLDivElement>(null);
152	  const [morphStage, setMorphStage] = useState(() => (morph ? modelingMorphStage(window.innerHeight) : null));
153	  const morphRef = useRef(morph);
154	  morphRef.current = morph;
155	  // Le contenu (header, Sélection, Corps — cf. CONTENT_REVEAL_THRESHOLD) n'a de sens que quand la
156	  // silhouette est assez proche de sa forme normale : trop petite (pilule ou panneaux Preview), il
157	  // ne resterait qu'un fragment arbitraire d'un texte/bouton bien plus grand qu'elle, pas quelque
158	  // chose de lisible. `true` par défaut (pas de morph, ou avant même son premier effet) : le
159	  // contenu est visible tant que rien ne dit explicitement qu'il faut l'estomper.
160	  const [contentRevealed, setContentRevealed] = useState(true);
161	
162	  // Layout effect : la première silhouette est posée avant le premier affichage (sinon une image
163	  // du panneau non clippé — donc en pleine forme rectangulaire normale — clignoterait).
164	  useLayoutEffect(() => {
165	    if (!morph || !panelRef.current) return;
166	    const stage = modelingMorphStage(window.innerHeight);
167	    setMorphStage(stage);
168	    const el = panelRef.current;
169	    let revealed = morph.direction !== 'enter'; // 'exit' pleinement affiché à t=0 (progress=0)
170	    setContentRevealed(revealed);
171	
172	    const apply = (progress: number) => {
173	      const t = morph.direction === 'exit' ? 1 - progress : progress;
174	      el.style.clipPath = `path('${modelingPathAt(morph.fromPreview, window.innerHeight, t, 0, -stage.dyOffset)}')`;
175	      const shouldReveal = t >= CONTENT_REVEAL_THRESHOLD;
176	      if (shouldReveal !== revealed) {
177	        revealed = shouldReveal;
178	        setContentRevealed(revealed);
179	      }
180	    };
181	
182	    apply(0);
183	    const start = performance.now();
184	    let raf = requestAnimationFrame(function tick(now) {
185	      const progress = Math.min(1, (now - start) / MODELING_MORPH_MS);
186	      apply(progress);
187	      if (progress < 1) {
188	        raf = requestAnimationFrame(tick);
189	      } else {
190	        el.style.clipPath = '';
191	        setMorphStage(null);
192	        morphRef.current?.onDone();
193	      }
194	    });
195	    return () => cancelAnimationFrame(raf);
196	    // `morph.direction`/`morph.fromPreview` sont figés pour la durée de CE morph (Index.tsx ne les
197	    // change jamais sans démonter/remonter un nouveau cycle) : seule l'identité de `morph`
198	    // (passant de undefined à défini) doit relancer l'effet.
199	  }, [morph]);
200	
201	  /** Le viewport a besoin de connaître l'état initial dès le montage du panneau. */

