30	const Index = () => {
31	  const [activeTab, setActiveTab] = useState<'3d-view' | 'settings' | 'developer'>('3d-view');
32	  const [activeCategory, setActiveCategory] = useState<string | null>(null);
33	  const [isPrinterConfigOpen, setIsPrinterConfigOpen] = useState(false);
34	  const [selectedPrinter, setSelectedPrinter] = useState('Prusa MK4');
35	  const [selectedFilament, setSelectedFilament] = useState('PLA Premium (eSUN / Prusament)');
36	  const [isSliceModalOpen, setIsSliceModalOpen] = useState(false);
37	  const [isSlicingProgressOpen, setIsSlicingProgressOpen] = useState(false);
38	  const [modelStatus, setModelStatus] = useState<ModelStatus | null>(null);
39	  const [isPreviewActive, setIsPreviewActive] = useState(false);
40	  const isPreviewActiveRef = useRef(isPreviewActive);
41	  isPreviewActiveRef.current = isPreviewActive;
42	  // Le temps que ModelingSidebar déforme sa propre silhouette entre la forme de la pilule/des deux
43	  // panneaux de Prévisualisation et sa forme normale — cf. le commentaire sur `onTabChange` plus
44	  // bas et le prop `morph` de ModelingSidebar. `null` = pas de morph en cours ; sinon, `direction`
45	  // indique le sens ('enter' : la pilule/Prévisualisation devient le panneau Modélisation, 'exit' :
46	  // l'inverse) et `fromPreview` l'état de Prévisualisation à l'autre bout du morph (pilule ou
47	  // panneaux Preview) — figé à l'instant du clic, lu depuis isPreviewActiveRef, PAS depuis
48	  // isPreviewActive : Sidebar mute ce dernier dans le même geste, avant qu'on ait la chance de lire
49	  // sa valeur de départ. Contrairement à l'ancienne approche (deux calques à synchroniser — un
50	  // verre animé séparé, puis le vrai panneau), c'est ICI le même élément, déjà affiché avec son
51	  // contenu réel, qui change de forme : plus de raccord entre deux éléments distincts, donc plus
52	  // de risque de clignotement à la jonction.
53	  const [modelingMorph, setModelingMorph] = useState<{ direction: 'enter' | 'exit'; fromPreview: boolean } | null>(null);
54	  const [statusBarRef, animateStatusBar] = useAnimate<HTMLDivElement>();
55	  const prevPreviewActiveRef = useRef(isPreviewActive);
56	
57	  // Au changement d'espace, la barre d'aide (TopRightMenu) passe par le coin bas gauche, là où
58	  // se trouve la barre de statut : celle-ci se rentre sous le bord de l'écran juste avant
59	  // (0,2 → 0,45 s ; la barre d'aide démarre à 0,495 s) et ressort une fois la barre d'aide
60	  // arrivée (1,1 s), pour ne pas se faire recouvrir.
61	  useEffect(() => {
62	    if (prevPreviewActiveRef.current === isPreviewActive) return;
63	    prevPreviewActiveRef.current = isPreviewActive;
64	    if (!statusBarRef.current) return;
65	    animateStatusBar(
