198	              return;
199	            }
200	            setModelingMorph({ direction: 'enter', fromPreview: false });
201	          } else if (tab !== 'settings' && isModeling) {
202	            // Sortie de Modélisation : `tab === 'box'` que ce soit vers Préparation ou vers
203	            // Prévisualisation (cf. handleLayerClick dans Sidebar.tsx, branche `entering`, qui

