file.content:
  // modelingMorph) joue le morph — cf. son prop `morph`.
  if (tab === 'settings' && !isModeling) {
    // L'état de départ (Préparation ou Prévisualisation) est lu MAINTENANT depuis
    // isPreviewActiveRef, avant que Sidebar ne le fasse passer à jour dans ce même geste.
    const fromPreview = isPreviewActiveRef.current;
    if (fromPreview) {
      // CategoriesSidebar (avec ses vrais panneaux) doit rester montée un rendu de plus,
      // `leavingToModeling` déjà vrai, pour que son panneau du bas ait la chance de capturer
      // ce variant `exit` avant d'être démonté au rendu suivant (cf. leavingToModeling) —
      // Framer Motion ne rejoue l'exit d'un composant qu'avec les props de son dernier rendu
      // monté, jamais celles du geste qui le démonte dans le même tick.
      setLeavingToModeling(true);
      requestAnimationFrame(() => {
        setModelingMorph({ direction: 'enter', fromPreview: true });
        setActiveTab('settings');
        setLeavingToModeling(false);
      });
      setIsPrinterConfigOpen(false);
      return;
    }
    setModelingMorph({ direction: 'enter', fromPreview: false });
  } else if (tab !== 'settings' && isModeling) {
    // Sortie de Modélisation : `tab === 'box'` que ce soit vers Préparation ou vers
    // Prévisualisation (cf. handleLayerClick dans Sidebar.tsx, branche `entering`, qui
    // passe `toPreview: true`) — la destination ne peut donc pas se lire depuis `tab` seul.
    setModelingMorph({ direction: 'exit', fromPreview: !!toPreview });
  }
  setActiveTab(tab === 'box' ? '3d-view' : tab);
  setIsPrinterConfigOpen(false);
}}

