const PREVIEW_DIVIDE_MS = 760;
const PREVIEW_MORPH_MS = PREVIEW_STRETCH_MS + PREVIEW_HOLD_MS + PREVIEW_DIVIDE_MS;

// Cascade de disparition des icônes de la pilule (Qualité/Solidité/Vitesse/...) avant un morph vers
// Modélisation (cf. leavingToModeling) : chacune s'estompe l'une après l'autre dans l'ordre
// d'affichage (gauche → droite), symétrique à la cascade d'apparition du contenu du panneau
// Modélisation à l'arrivée (cf. CONTENT_STAGGER_MS dans ModelingSidebar.tsx). Doit tenir dans
// FROM_PREVIEW_FADE_MS (= ELEMENTS_FADE_MS, le temps mort avant que la déformation ne commence) :
// avec ~8 catégories et un stagger de 30ms, la dernière icône démarre à 210ms, finit vers 340ms —
// légèrement après le seuil, un dépassement discret et sans conséquence puisque la pilule elle-même
// a déjà disparu de l'écran à ce moment (cf. plus bas).
const PILL_ICON_STAGGER_MS = 0.03;
const PILL_ICON_FADE_MS = 0.16;

const pillIconsContainerVariants = {
  visible: { transition: { staggerChildren: PILL_ICON_STAGGER_MS } },
  hidden: { transition: { staggerChildren: PILL_ICON_STAGGER_MS } },
};

const pillIconVariants = {
  visible: { opacity: 1, y: 0, transition: { duration: PILL_ICON_FADE_MS, ease: [0.4, 0, 0.2, 1] } },
  hidden: { opacity: 0, y: -6, transition: { duration: PILL_ICON_FADE_MS, ease: [0.4, 0, 0.2, 1] } },
};

