const target = {x:0,y:-116,w:268,h:800,r:18}; // approx viewport 992

const ELEMENTS_FADE_MS = 260;
const PILL_STRETCH_MS = 550;
const MODELING_MORPH_MS = ELEMENTS_FADE_MS + PILL_STRETCH_MS;

function stretchW(from, to, tLocal) {
  const ew = ease.inOutCubic(clamp01((tLocal - 0.12) / 0.88));
  return from.w + (to.w - from.w) * ew;
