import { chromium } from 'playwright';

const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1600, height: 1000 } });

await page.goto('http://localhost:8082', { waitUntil: 'networkidle' });
await page.waitForTimeout(800);

// Inject a frame-by-frame width/clip-path recorder for the ModelingSidebar panel.
await page.evaluate(() => {
  window.__widthLog = [];
  window.__recording = false;
  function findPanel() {
    // .panel class is CSS-modules-hashed; find via data-apex-chrome-panel container's child.
    const containers = document.querySelectorAll('[data-apex-chrome-panel]');
    for (const c of containers) {
      const child = c.firstElementChild;
      if (child && getComputedStyle(child).backdropFilter?.includes('blur')) {
        // Heuristic: modeling panel container has position fixed set via inline style sometimes.
      }
    }
    return null;
  }
  function tick() {
    if (window.__recording) {
      // Grab ALL elements with a clip-path style set (our morphing panel).
      const all = document.querySelectorAll('div');
      for (const el of all) {
        if (el.style.clipPath) {
          const r = el.getBoundingClientRect();
          window.__widthLog.push({ t: performance.now(), w: r.width, h: r.height, left: r.left, top: r.top });
        }
      }
    }
    requestAnimationFrame(tick);
  }
  requestAnimationFrame(tick);
});

const modelingBtn = page.locator('button', { hasText: 'Modélisation' }).first();
await modelingBtn.waitFor({ state: 'visible', timeout: 10000 });

await page.evaluate(() => { window.__recording = true; window.__widthLog = []; });
await modelingBtn.click();
await page.waitForTimeout(3500);
await page.evaluate(() => { window.__recording = false; });

const log = await page.evaluate(() => window.__widthLog);
console.log('SAMPLES:', log.length);
// Print width deltas to spot spikes
let prevW = null;
for (const s of log) {
  if (prevW !== null && Math.abs(s.w - prevW) > 15) {
    console.log('SPIKE at t=', s.t.toFixed(1), 'w=', s.w.toFixed(1), 'prevW=', prevW.toFixed(1), 'h=', s.h.toFixed(1), 'left=', s.left.toFixed(1), 'top=', s.top.toFixed(1));
  }
  prevW = s.w;
}
console.log('First 10:', JSON.stringify(log.slice(0, 10)));
console.log('Last 10:', JSON.stringify(log.slice(-10)));

await browser.close();

