import { chromium } from 'playwright';

const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1600, height: 1000 } });
page.on('console', (m) => { if (m.type() === 'error') console.log('PAGE ERROR:', m.text()); });

await page.goto('http://localhost:8082', { waitUntil: 'networkidle' });
await page.waitForTimeout(800);

const modelingBtn = page.locator('button', { hasText: 'Modélisation' }).first();
await modelingBtn.waitFor({ state: 'visible', timeout: 10000 });

// Start a rAF-driven recorder BEFORE clicking, tracking every div with an active clip-path.
await page.evaluate(() => {
  window.__log = [];
  window.__rec = true;
  function tick() {
    if (window.__rec) {
      document.querySelectorAll('div').forEach((el) => {
        const cp = el.style.clipPath;
        if (cp) {
          const r = el.getBoundingClientRect();
          window.__log.push({ t: performance.now(), w: +r.width.toFixed(1), h: +r.height.toFixed(1) });
        }
      });
    }
    if (window.__log.length < 5000) requestAnimationFrame(tick);
  }
  requestAnimationFrame(tick);
});

await modelingBtn.click();
await page.waitForTimeout(3000);
await page.evaluate(() => { window.__rec = false; });

const log = await page.evaluate(() => window.__log);
console.log('SAMPLES:', log.length);
console.log(JSON.stringify(log));

await browser.close();

