export const LiquidGlassShadow: React.FC<LiquidGlassMorphProps> = ({
  left,
  top,
  width,
  height,
  duration,
  pathAt,
  reverse = false,
  onDone,
}) => {
  const shadowShapeRef = useRef<HTMLDivElement>(null);
  const shadowClipRef = useRef<HTMLDivElement>(null);
  const pathAtRef = useRef(pathAt);
  pathAtRef.current = pathAt;
  const onDoneRef = useRef(onDone);
  onDoneRef.current = onDone;

  useLayoutEffect(() => {
    const M = SHADOW_MARGIN;
    const outer = `M0 0L${width + 2 * M} 0L${width + 2 * M} ${height + 2 * M}L0 ${height + 2 * M}Z`;

    const apply = (progress: number) => {
      const t = reverse ? 1 - progress : progress;
      const shifted = pathAtRef.current(t, M, M);
      if (shadowShapeRef.current) shadowShapeRef.current.style.clipPath = `path('${shifted}')`;
      if (shadowClipRef.current) shadowClipRef.current.style.clipPath = `path(evenodd, '${outer}${shifted}')`;
    };

    apply(0);
    const start = performance.now();
    let raf = requestAnimationFrame(function tick(now) {
      const progress = Math.min(1, (now - start) / duration);
      apply(progress);
      if (progress < 1) raf = requestAnimationFrame(tick);
      else onDoneRef.current?.();
    });
    return () => cancelAnimationFrame(raf);
  }, [width, height, duration, reverse]);

  return (
    <div
      ref={shadowClipRef}
      className={styles.shadowClip}
      style={{
