file.content:
$accent: #00f0ff;
$panel-bg: rgba(10, 15, 26, 0.25);
$panel-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.4), 0 2px 8px 0 rgba(0, 0, 0, 0.3);

.container {
  position: fixed;
  top: 96px;
  left: 24px;
  bottom: 96px;
  width: 268px;
  // Même niveau que les autres panneaux principaux (FileSidebar, Sidebar, SliceSidebar…) :
  // au-dessus du rideau de transition d'espace (SpaceTransitionOverlay, z-index 30) ET du calque
  // d'ombre du morph (LiquidGlassMorph, $morph-z 999, cf. ModelingSidebar.tsx), qui doit rester
  // SOUS ce panneau pendant que sa silhouette change de forme.
  z-index: 1000;
  display: flex;
  flex-direction: column;
  pointer-events: none;
}

.panel {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-height: 0;
  background: $panel-bg;
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
  border: none;
  border-radius: 18px;
  box-shadow: $panel-shadow;
  pointer-events: auto;
  overflow: hidden;

  // Pendant un morph d'espace (cf. la prop `morph` de ModelingSidebar) : la silhouette réelle est
  // dessinée par le `clip-path` animé (cf. useLayoutEffect dans ModelingSidebar.tsx), qui inclut
  // déjà ses propres coins arrondis — `border-radius` n'aurait plus aucun effet visible sur un
  // contour non rectangulaire mais resterait coûteux à calculer ; `box-shadow` ne suivrait de toute
  // façon jamais un `clip-path` complexe (cf. LiquidGlassShadow, le calque qui le remplace).
  &.morphing {
    border-radius: 0;
    box-shadow: none;
  }
}

