const panelRef = useRef<HTMLDivElement>(null);
const shadowRef = useRef<LiquidGlassShadowHandle>(null);
const [morphStage, setMorphStage] = useState(() => (morph ? modelingMorphStage(window.innerHeight) : null));
const morphRef = useRef(morph);
morphRef.current = morph;
// Le contenu (header, Sélection, Corps — cf. CONTENT_REVEAL_THRESHOLD) n'a de sens que quand la
// silhouette est assez proche de sa forme normale : trop petite (pilule ou panneaux Preview), il
// ne resterait qu'un fragment arbitraire d'un texte/bouton bien plus grand qu'elle, pas quelque
// chose de lisible. Calculé dès l'état initial (pas dans le layout effect plus bas, qui ne
// corrigerait qu'APRÈS un premier rendu à `true` — un clignotement bref le temps de ce premier
// rendu, avant que l'effet n'ait la chance de le rectifier) : `true` seulement si aucun morph
// 'enter' n'est en cours dès ce tout premier rendu ('exit' démarre pleinement affiché, à t = 1).
const [contentRevealed, setContentRevealed] = useState(() => morph?.direction !== 'enter');

// Layout effect : la première silhouette est posée avant le premier affichage (sinon une image
// du panneau non clippé — donc en pleine forme rectangulaire normale — clignoterait).
useLayoutEffect(() => {
  if (!morph || !panelRef.current) return;
  const stage = modelingMorphStage(window.innerHeight);
  setMorphStage(stage);
  const el = panelRef.current;
  let revealed = morph.direction !== 'enter'; // 'exit' pleinement affiché à t=0 (progress=0)
  setContentRevealed(revealed);

  const pathAt = (t: number, dx: number, dy: number) =>
    modelingPathAt(morph.fromPreview, window.innerHeight, t, dx, dy - stage.dyOffset);

  const apply = (progress: number) => {
    const t = morph.direction === 'exit' ? 1 - progress : progress;
    el.style.clipPath = `path('${pathAt(t, 0, 0)}')`;
    // MÊME frame, MÊME `progress` que le panneau réel ci-dessus : deux boucles RAF séparées
    // (une pour le panneau, une pour l'ombre) dériveraient de quelques millisecondes l'une de
    // l'autre, rendant les deux silhouettes visibles décalées — cf. le commentaire de
    // LiquidGlassShadow.
    applyLiquidGlassShadow(shadowRef, pathAt, stage.width, stage.height, morph.direction === 'exit', progress);
    const shouldReveal = t >= CONTENT_REVEAL_THRESHOLD;
    if (shouldReveal !== revealed) {
      revealed = shouldReveal;
      setContentRevealed(revealed);
    }
  };

  const duration = modelingMorphDuration(morph.fromPreview);
  apply(0);
  const start = performance.now();
  let raf = requestAnimationFrame(function tick(now) {
    const progress = Math.min(1, (now - start) / duration);
    apply(progress);
    if (progress < 1) {
      raf = requestAnimationFrame(tick);
    } else {
      el.style.clipPath = '';
      setMorphStage(null);
      morphRef.current?.onDone();
    }

