import { chromium } from 'playwright';

const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1600, height: 1000 } });

await page.goto('http://localhost:8082', { waitUntil: 'networkidle' });
await page.waitForTimeout(800);

// Slow down performance.now() by a factor of 20 so a 550ms animation takes ~11s — easy to observe
// and screenshot frame by frame.
await page.addInitScript(() => {
  const origNow = performance.now.bind(performance);
  const t0 = origNow();
  const FACTOR = 20;
  performance.now = () => t0 + (origNow() - t0) / FACTOR;
});
await page.reload({ waitUntil: 'networkidle' });
await page.waitForTimeout(800);

const modelingBtn = page.locator('button', { hasText: 'Modélisation' }).first();
await modelingBtn.waitFor({ state: 'visible', timeout: 10000 });

// Track every frame's computed style (background-color / backdrop-filter / clip-path) of the panel.
await page.evaluate(() => {
  window.__frames = [];
  window.__rec = false;
  function findPanel() {
    // Any div with an inline clip-path style AND our morph z-index (1000 container -> child .panel)
    return [...document.querySelectorAll('div')].filter(el => el.style.clipPath);
  }
  function tick() {
    if (window.__rec) {
      const panels = findPanel();
      for (const el of panels) {
        const cs = getComputedStyle(el);
        window.__frames.push({
          t: performance.now(),
          bg: cs.backgroundColor,
          clip: el.style.clipPath ? el.style.clipPath.slice(0, 20) : '(none)',
          w: el.getBoundingClientRect().width,
        });
      }
    }
    if (window.__frames.length < 3000) requestAnimationFrame(tick);
  }
  requestAnimationFrame(tick);
});

await page.evaluate(() => { window.__rec = true; });
await modelingBtn.click();
await page.waitForTimeout(15000);
await page.evaluate(() => { window.__rec = false; });

const frames = await page.evaluate(() => window.__frames);
console.log('TOTAL FRAMES:', frames.length);
// Detect transitions in bg (transparent vs not) or clip being '(none)'
let prevBg = null;
for (const f of frames) {
  if (f.bg !== prevBg) {
    console.log(`t=${f.t.toFixed(1)} bg=${f.bg} clip=${f.clip} w=${f.w.toFixed(1)}`);
    prevBg = f.bg;
  }
}

await browser.close();

