import { chromium } from 'playwright';

const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1600, height: 1000 } });

await page.addInitScript(() => {
  const origNow = performance.now.bind(performance);
  const t0 = origNow();
  const FACTOR = 15;
  performance.now = () => t0 + (origNow() - t0) / FACTOR;
});

await page.goto('http://localhost:8082', { waitUntil: 'networkidle' });
await page.waitForTimeout(800);

const modelingBtn = page.locator('button', { hasText: 'Modélisation' }).first();
await modelingBtn.waitFor({ state: 'visible', timeout: 10000 });

// Identify .panel precisely: the element whose parent has position:fixed inline style with our
// stage geometry AND whose own background matches $panel-bg (10,15,26,.25).
await page.evaluate(() => {
  window.__frames = [];
  window.__rec = false;
  function tick() {
    if (window.__rec) {
      document.querySelectorAll('div').forEach((el) => {
        if (!el.style.clipPath) return;
        const cs = getComputedStyle(el);
        // Only track elements that look like our modeling panel (has backdrop-filter blur).
        if (cs.backdropFilter && cs.backdropFilter.includes('blur')) {
          window.__frames.push({
            t: +performance.now().toFixed(1),
            bg: cs.backgroundColor,
            opacity: cs.opacity,
            clipLen: el.style.clipPath.length,
          });
        }
      });
    }
    if (window.__frames.length < 4000) requestAnimationFrame(tick);
  }
  requestAnimationFrame(tick);
});

await page.evaluate(() => { window.__rec = true; });
await modelingBtn.click();
await page.waitForTimeout(12000);
await page.evaluate(() => { window.__rec = false; });

const frames = await page.evaluate(() => window.__frames);
console.log('TOTAL:', frames.length);
let prev = null;
for (const f of frames) {
  const key = f.bg + '|' + f.opacity;
  if (key !== prev) {
    console.log(`t=${f.t} bg=${f.bg} opacity=${f.opacity} clipLen=${f.clipLen}`);
    prev = key;
  }
}
await browser.close();

