<motion.div
  className={styles.container}
  data-apex-chrome-panel
  style={
    morphStage
      ? { position: 'fixed', left: morphStage.left, top: morphStage.top, width: morphStage.width, height: morphStage.height, bottom: 'auto' }
      : undefined
  }
  // L'animation d'entrée/sortie complète (exit, hors morph — ex. Dev) est portée ICI, sur ce
  // conteneur, PLUTÔT que sur .panel ci-dessous : Framer Motion réécrit le `style` inline des
  // éléments qu'il anime à chaque re-render (ses propres MotionValues ne connaissent pas
  // `clipPath`, posé en dehors de son système via `panelRef.current.style.clipPath = …`), et
  // écrase silencieusement ce clip-path — le panneau redevenait alors un instant transparent
  // (aucune découpe), avant que le prochain tick de la boucle RAF ne le repose. `.panel`
  // reste donc un <div> simple, jamais un motion.div.
  initial={false}
  animate={{ opacity: 1, x: 0 }}
  exit={{ opacity: 0, x: -24 }}
  transition={{ duration: 0 }}
>
  <div

