file.content:
export const MODELING_BOTTOM_MARGIN = 96;

// Temps mort au tout début du morph 'enter' (t reste figé sur la forme de départ), pendant lequel
// les éléments d'interface qui n'ont pas leur place dans l'espace Modélisation (ModelStatusBox, et
// pour fromPreview le panneau du bas de Prévisualisation, cf. FROM_PREVIEW_FADE_MS/
// leavingToModeling dans CategoriesSidebar.tsx) disparaissent en fondu-glissement — la déformation
// du panneau restant (pilule ou panneau du haut) ne commence qu'UNE FOIS ce temps écoulé, jamais en
// parallèle. Même durée dans les deux cas (fromPreview ou non) pour un rythme cohérent.
export const ELEMENTS_FADE_MS = 260;

// Départ pilule seule (Préparation) : ELEMENTS_FADE_MS (rien ne bouge) puis étirement direct vers
// Modélisation.
export const PILL_STRETCH_MS = 550;
export const MODELING_MORPH_MS = ELEMENTS_FADE_MS + PILL_STRETCH_MS;

// Départ Prévisualisation (fromPreview) : mêmes deux temps séquentiels, jamais de fusion entre les
// deux panneaux — le panneau du bas n'est déjà plus dans le morph liquide lui-même :
//  1. ELEMENTS_FADE_MS : temps mort correspondant à la disparition de ModelStatusBox ET du panneau
//     du bas (cf. FROM_PREVIEW_FADE_MS, alias du même délai côté CategoriesSidebar.tsx).
//  2. FROM_PREVIEW_STRETCH_MS : le panneau du haut s'étire directement vers Modélisation
//     (stretchPath), sans jamais passer par une forme fusionnée avec le bas.
export const FROM_PREVIEW_FADE_MS = ELEMENTS_FADE_MS;
export const FROM_PREVIEW_STRETCH_MS = 480;
export const MODELING_MORPH_FROM_PREVIEW_MS = FROM_PREVIEW_FADE_MS + FROM_PREVIEW_STRETCH_MS;

export const modelingGeometry = (viewportH: number): GlassRect => ({
  x: 0,
  y: MODELING_Y,
  w: MODELING_W,
  h: viewportH - MODELING_TOP - MODELING_BOTTOM_MARGIN,
  r: MODELING_R,
});

/** Durée totale du morph Modélisation selon l'état de départ/arrivée. */
export const modelingMorphDuration = (fromPreview: boolean) =>
  fromPreview ? MODELING_MORPH_FROM_PREVIEW_MS : MODELING_MORPH_MS;

/**
 * Contour du panneau Modélisation à l'instant t ∈ [0, 1] (fraction de modelingMorphDuration) :
 * t = 0 la pilule (ou le panneau du haut de Prévisualisation si `fromPreview` — le panneau du bas
 * ne fait JAMAIS partie de cette forme), t = 1 le panneau Modélisation. Les ELEMENTS_FADE_MS
 * premières millisecondes ne bougent jamais (cf. leur commentaire) : c'est le temps laissé aux
 * autres éléments d'interface pour disparaître avant que la déformation ne commence. `reverse` sur
 * le composant qui consomme ce chemin joue la même timeline en sens inverse.
 */
export const modelingPathAt = (
  fromPreview: boolean,
  viewportH: number,
  t: number,
  dx: number,
  dy: number,
) => {
  const target = modelingGeometry(viewportH);
  if (fromPreview) {
    const { upper } = previewGeometry(viewportH);
    const ms = t * MODELING_MORPH_FROM_PREVIEW_MS;
    if (ms < FROM_PREVIEW_FADE_MS) return stretchPath(upper, upper, 0, dx, dy);
    return stretchPath(upper, target, (ms - FROM_PREVIEW_FADE_MS) / FROM_PREVIEW_STRETCH_MS, dx, dy);
  }
  const ms = t * MODELING_MORPH_MS;
  if (ms < ELEMENTS_FADE_MS) return stretchPath(PILL, PILL, 0, dx, dy);
  return stretchPath(PILL, target, (ms - ELEMENTS_FADE_MS) / PILL_STRETCH_MS, dx, dy);
};

/** Stage englobant la géométrie de départ ET celle d'arrivée du morph Modélisation. */

