  activeTab={activeTab}
  onTabChange={(tab, toPreview) => {
    // Passage vers ou hors de Modélisation : le rideau plein écran (déjà déclenché par
    // Sidebar avant cet appel, cf. playSpaceTransition) masque le changement de `main`,
    // pendant lequel ModelingSidebar (montée en permanence tant que isModeling ||
    // modelingMorph) joue le morph — cf. son prop `morph`.
    if (tab === 'settings' && !isModeling) {
      // L'état de départ (Préparation ou Prévisualisation) est lu MAINTENANT depuis
      // isPreviewActiveRef, avant que Sidebar ne le fasse passer à jour dans ce même geste.
      // `leavingToModeling` est déjà vrai depuis le clic (cf. apex-entering-modeling) : le
      // panneau du bas de Prévisualisation, s'il y en a un, a donc largement eu le temps de
      // finir sa disparition avant que CategoriesSidebar ne démonte à CE rendu (celui-ci) —
      // c'est justement pourquoi il ne faut PAS le repasser à `false` ici : Framer Motion ne
      // capture le variant `exit` d'un composant qu'avec les props de son DERNIER rendu monté
      // (celui-ci, précisément), donc `leavingToModeling` doit encore valoir `true` à cet
      // instant. Il est remis à `false` séparément, une fois CategoriesSidebar effectivement
      // démontée (cf. l'effet dédié plus bas), pour être prêt pour le prochain cycle.
      setModelingMorph({ direction: 'enter', fromPreview: isPreviewActiveRef.current });
    } else if (tab !== 'settings' && isModeling) {
      // Sortie de Modélisation : `tab === 'box'` que ce soit vers Préparation ou vers
      // Prévisualisation (cf. handleLayerClick dans Sidebar.tsx, branche `entering`, qui
      // passe `toPreview: true`) — la destination ne peut donc pas se lire depuis `tab` seul.
      setModelingMorph({ direction: 'exit', fromPreview: !!toPreview });
    }
    setActiveTab(tab === 'box' ? '3d-view' : tab);
    setIsPrinterConfigOpen(false);
  }}
  onOpenModel={handleOpenModel}
/>

<TopRightMenu />
<AxisSidebar />
<ViewCube />

{/* Les panneaux slicer et le panneau modélisation s'excluent mutuellement : basculer
    d'onglet échange les deux avec un fondu, plutôt que de les empiler — sauf pendant un
    morph vers ou hors de Modélisation (modelingMorph) : ModelingSidebar reste alors montée
    (elle porte elle-même toute l'animation visible, cf. son prop `morph`) pendant que
    l'autre côté n'apparaît qu'une fois le morph terminé. */}
<AnimatePresence mode={modelingMorph ? 'sync' : 'wait'}>
  {isModeling || modelingMorph?.direction === 'exit' ? (
    <React.Fragment key="modeling">
      <ModelingSidebar
        morph={
          modelingMorph
            ? { ...modelingMorph, onDone: () => setModelingMorph(null) }
            : undefined
        }
      />
    </React.Fragment>
  ) : (
    <React.Fragment key="slicer">
      <CategoriesSidebar
        activeCategory={activeCategory}
        onSelectCategory={(cat) => {
          setActiveCategory(cat);
          if (cat) setIsPrinterConfigOpen(false);
        }}
        // Après un morph de sortie de Modélisation vers Prévisualisation (cf. modelingMorph,
        // consommé au dernier rendu où il valait encore 'exit' ci-dessus), les deux panneaux
        // réels doivent être affichés tels quels dès ce premier rendu, sans y rejouer la
        // mitose normale — le morph a déjà eu lieu visuellement, sur ModelingSidebar.
        initialPreviewActive={isPreviewActive}
        leavingToModeling={leavingToModeling}
      />

      <PrinterConfigSidebar
        isOpen={isPrinterConfigOpen}
        onClose={() => setIsPrinterConfigOpen(false)}
        selectedPrinter={selectedPrinter}
        onSelectPrinter={setSelectedPrinter}
        selectedFilament={selectedFilament}
        onSelectFilament={setSelectedFilament}
      />

      <SliceSidebar onSlice={handleSlice} />
    </React.Fragment>
  )}
</AnimatePresence>

