cd /tmp/pwtest && cat > probe.mjs << 'EOF'
import { chromium } from 'playwright';

const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1600, height: 1000 } });
const cdp = await page.context().newCDPSession(page);
await cdp.send('Emulation.setCPUThrottlingRate', { rate: 4 });
const errors = [];
page.on('pageerror', (e) => errors.push(e.message));

await page.goto('http://localhost:8082', { waitUntil: 'networkidle' });
await page.waitForTimeout(1500);

await page.evaluate(() => {
  window.__v = [];
  window.__label = 'init';
  window.__stats = {};
  const cls = (el) => (typeof el.className === 'string' ? el.className : '');
  function tick() {
    const divs = document.querySelectorAll('div');
    let P = null, pill = null, upper = null;
    for (const el of divs) {
      const c = cls(el);
      if (!P && /_panel_/.test(c) && el.parentElement && /_container_/.test(cls(el.parentElement)) && el.parentElement.hasAttribute('data-apex-chrome-panel')) P = el;
      if (!pill && /categoriesToolbar/.test(c)) pill = el;
      if (!upper && /previewPanelUpper/.test(c)) upper = el;
    }
    const s = (window.__stats[window.__label] ||= { frames: 0, morphFrames: 0 });
    s.frames++;
    if (P) {
      const morphing = /morphing/.test(cls(P));
      const clipEmpty = !P.style.clipPath;
      const stage = !!P.parentElement.style.width;
      if (morphing) s.morphFrames++;
      if (morphing && clipEmpty) window.__v.push([window.__label, 'A: .morphing sans clip-path (flash transparent)']);
      if (!morphing && stage) window.__v.push([window.__label, 'B: stage sans .morphing (carré plus large)']);
      if (morphing && !stage) window.__v.push([window.__label, 'B2: .morphing sans stage']);
    }
    const pillVisible = pill && parseFloat(getComputedStyle(pill).opacity) > 0.5;
    if (!P && !pillVisible && !upper) window.__v.push([window.__label, 'C: aucun panneau gauche visible (trou de bascule)']);
    requestAnimationFrame(tick);
